import React from 'react';
import { GoogleMap, useJsApiLoader, Marker, Circle } from '@react-google-maps/api';

const containerStyle = { width: '100%', height: '100%' };
const defaultCenter = { lat: -6.208326360287679, lng: 106.79637092720068 };
const STORE_ICON = 'https://maps.google.com/mapfiles/ms/icons/green-dot.png';

const toPos = (e) => ({ lat: e.latLng.lat(), lng: e.latLng.lng() });

/**
 * Peta serbaguna.
 * - markers: daftar posisi (penanda biasa)
 * - store: posisi toko (penanda hijau)
 * - pin + onPinChange: titik pengantaran/lokasi yang bisa digeser
 * - onMapClick: dipanggil saat peta diklik
 * - circle: { center, radiusKm } untuk menggambar lingkaran jangkauan
 */
function GoogleMapComponent({ center, zoom = 14, markers = [], store = null, pin = null, onPinChange, onMapClick, circle = null }) {
  const { isLoaded, loadError } = useJsApiLoader({
    id: 'google-map-script',
    googleMapsApiKey: process.env.REACT_APP_GOOGLE_MAPS_API_KEY || 'YOUR_API_KEY_HERE',
  });

  // Titik awal hanya dibaca sekali supaya peta tidak "melompat" kembali saat halaman dirender ulang.
  const [initialCenter] = React.useState(center || store || defaultCenter);
  const mapRef = React.useRef(null);

  const onLoad = React.useCallback((map) => { mapRef.current = map; }, []);
  const onUnmount = React.useCallback(() => { mapRef.current = null; }, []);

  // Saat pin berubah: tampilkan toko & pin sekaligus, atau pusatkan ke pin.
  React.useEffect(() => {
    const map = mapRef.current;
    if (!isLoaded || !map || !pin || !window.google) return;
    if (store) {
      const b = new window.google.maps.LatLngBounds();
      b.extend(store); b.extend(pin);
      map.fitBounds(b, 70);
    } else {
      map.panTo(pin);
    }
  }, [isLoaded, pin, store]);

  if (loadError) {
    return <div className="w-full h-full bg-gray-100 flex items-center justify-center text-sm text-gray-500 px-4 text-center">Peta tidak dapat dimuat. Periksa koneksi internet Anda.</div>;
  }
  if (!isLoaded) {
    return <div className="w-full h-full bg-gray-100 flex items-center justify-center text-gray-500">Memuat Peta...</div>;
  }

  return (
    <GoogleMap
      mapContainerStyle={containerStyle}
      center={initialCenter}
      zoom={zoom}
      onLoad={onLoad}
      onUnmount={onUnmount}
      onClick={onMapClick ? (e) => onMapClick(toPos(e)) : undefined}
      options={{ maxZoom: 19, streetViewControl: false, mapTypeControl: false, fullscreenControl: false }}
    >
      {circle && Number(circle.radiusKm) > 0 && (
        <Circle
          center={circle.center}
          radius={Number(circle.radiusKm) * 1000}
          options={{ strokeColor: '#059669', strokeOpacity: 0.8, strokeWeight: 2, fillColor: '#10b981', fillOpacity: 0.08, clickable: false }}
        />
      )}
      {markers.map((pos, index) => (
        <Marker key={index} position={pos} />
      ))}
      {store && <Marker position={store} icon={STORE_ICON} title="Lokasi toko" />}
      {pin && (
        <Marker
          position={pin}
          title="Titik pengantaran"
          draggable={!!onPinChange}
          onDragEnd={onPinChange ? (e) => onPinChange(toPos(e)) : undefined}
        />
      )}
    </GoogleMap>
  );
}

export default React.memo(GoogleMapComponent);

/* ---------- pencarian alamat (Google Geocoding) ---------- */

// Cari koordinat dari teks alamat. `near` (opsional) memprioritaskan hasil di sekitar toko.
export function geocodeAddress(address, near) {
  return new Promise((resolve, reject) => {
    if (!window.google || !window.google.maps || !window.google.maps.Geocoder) {
      reject(new Error('Peta belum siap. Tunggu sebentar lalu coba lagi.'));
      return;
    }
    const req = { address, region: 'id', componentRestrictions: { country: 'ID' } };
    if (near) {
      const d = 0.4;
      req.bounds = { south: near.lat - d, north: near.lat + d, west: near.lng - d, east: near.lng + d };
    }
    new window.google.maps.Geocoder().geocode(req, (results, status) => {
      if (status === 'OK' && results && results[0]) {
        const loc = results[0].geometry.location;
        resolve({ lat: loc.lat(), lng: loc.lng(), label: results[0].formatted_address });
      } else if (status === 'ZERO_RESULTS') {
        reject(new Error('Alamat tidak ditemukan. Tambahkan nama jalan, kelurahan, atau kota, atau klik langsung di peta.'));
      } else if (status === 'REQUEST_DENIED') {
        reject(new Error('Pencarian alamat belum aktif (Geocoding API belum diaktifkan untuk kunci peta). Klik langsung di peta untuk menandai lokasi.'));
      } else {
        reject(new Error('Pencarian alamat gagal. Coba lagi, atau klik langsung di peta.'));
      }
    });
  });
}

// Cari alamat dari koordinat. Tidak pernah melempar error: mengembalikan null bila gagal.
export function reverseGeocode(pos) {
  return new Promise((resolve) => {
    if (!window.google || !window.google.maps || !window.google.maps.Geocoder) { resolve(null); return; }
    new window.google.maps.Geocoder().geocode({ location: pos, region: 'id' }, (results, status) => {
      resolve(status === 'OK' && results && results[0] ? results[0].formatted_address : null);
    });
  });
}
